// PCB stores necessary state for context switch
struct PCB {
    int pid;
    Registers cpu_state; // Saved CPU registers/PC
    int quantum;         // Time remaining until forced yield
};

// The Timer Interrupt Service Routine (ISR)
void timer_interrupt_handler(Registers* r) {
    // 1. Save context of the interrupted process
    CurrentProcess->cpu_state = *r;
    CurrentProcess->quantum--;

    if (CurrentProcess->quantum <= 0) {
        CurrentProcess->state = READY;

        // 2. Run the scheduler (Time slice expired)
        NextProcess = Scheduler.select_next();

        // 3. Load context of the new process
        CurrentProcess = NextProcess;
        *r = CurrentProcess->cpu_state;
    }

    // 4. Reset/Acknowledge the hardware timer
    HW_TIMER_ACK();
}
